namespace LiteSpec.Maintain.Validate.Repository;

/// <summary>
///     The contextual field catalog: one row per record schema field naming the
///     record type that carries it, its word class, its coarse shape, and its
///     meaning in that record type. A field name reads in its record type, so the
///     same name carries its own shape and meaning per record type. The retired
///     synonyms below fail validation everywhere, and four names read only inside
///     the record type that owns them.
/// </summary>
/// <follows>litespec/core/authoring#run-repeatable-authoring-checks</follows>
internal static class FieldCatalog
{
    /// <summary>The fifteen word classes a field name reads as.</summary>
    internal enum FieldWordClass
    {
        /// <summary>A fixed noun: the record type, identifier, title, or name.</summary>
        Identity,

        /// <summary>A single canonical noun holding a closed-set value.</summary>
        Classification,

        /// <summary>A typed plural noun holding an array of objects or child entries.</summary>
        Structure,

        /// <summary>An active present-tense verb holding one link or a list of links.</summary>
        ForwardLink,

        /// <summary>basedOn, a past-participle By form, or via: what the record rests on or travels through.</summary>
        AuthorityLink,

        /// <summary>A singular role noun holding one typed link.</summary>
        RoleLink,

        /// <summary>A plain technical noun holding a scalar, enum, or value shape.</summary>
        DataType,

        /// <summary>A When name or condition holding one clause.</summary>
        Condition,

        /// <summary>A reason, rationale, or Because name holding one clause.</summary>
        Reason,

        /// <summary>An On, From, To, Window, Timeout, Delay, or duration name holding an ISO date or duration.</summary>
        DatesDurations,

        /// <summary>The timeZone name holding an IANA zone string.</summary>
        TimeZone,

        /// <summary>A bare present-tense predicate holding true or false.</summary>
        Boolean,

        /// <summary>A plain noun holding a sentence or a localized map.</summary>
        Prose,

        /// <summary>A canonical scope noun holding what the record covers.</summary>
        Scope,

        /// <summary>A canonical noun holding a structured mechanism or policy.</summary>
        Mechanics,
    }

    /// <summary>One catalog row: the record type that carries the field, the field name, its word class, its coarse shape, and its meaning.</summary>
    /// <param name="RecordType">The schema definition that carries the field.</param>
    /// <param name="Field">The field name.</param>
    /// <param name="WordClass">The word class the name reads as.</param>
    /// <param name="Shape">The coarse shape: string, array, object, boolean, integer, or any.</param>
    /// <param name="Meaning">What the field states in its record type, in one phrase.</param>
    public sealed record Entry(string RecordType, string Field, FieldWordClass WordClass, string Shape, string Meaning);

